/* V1.6.3 · diagnóstico exportable del app */
(()=>{
'use strict';
const VERSION='1.6.3';
const STARTED_AT=Date.now();
const MAX_EVENTS=40;
const events=[];
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clip=(s,n=220)=>{s=String(s??'').replace(/\s+/g,' ').trim();return s.length>n?s.slice(0,n)+'…':s;};
const nowIso=()=>new Date().toISOString();
function addEvent(type,detail){events.push({at:nowIso(),type:String(type||'event'),detail:clip(detail,700)});if(events.length>MAX_EVENTS)events.splice(0,events.length-MAX_EVENTS);}
window.addEventListener('error',e=>addEvent('js_error',`${e.message||'Error'} @ ${e.filename||'?'}:${e.lineno||0}:${e.colno||0}`));
window.addEventListener('unhandledrejection',e=>addEvent('promise_rejection',e.reason?.stack||e.reason?.message||String(e.reason||'rechazo sin detalle')));
function wrapCallback(name,type,detailFn){const old=window[name];if(typeof old!=='function'||old.__cecDiagWrapped)return;const wrapped=function(...args){try{addEvent(type,detailFn?detailFn(args):name);}catch(_){ }return old.apply(this,args);};wrapped.__cecDiagWrapped=true;window[name]=wrapped;}
wrapCallback('__cecReceiveSheet','sheet_ok',a=>`${a[0]||'?'} · payload base64 ${String(a[1]||'').length} chars`);
wrapCallback('__cecSheetError','sheet_error',a=>`${a[0]||'?'} · ${a[1]||'sin detalle'}`);
wrapCallback('__cecReceiveTerritoryImage','territory_map_ok',a=>`Territorio ${a[0]||'?'} · ${a[2]||'?'}×${a[3]||'?'} px`);
wrapCallback('__cecTerritoryImageError','territory_map_error',a=>`Territorio ${a[0]||'?'} · ${a[1]||'sin detalle'}`);
function readJson(key,fallback){try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw):fallback;}catch(e){return fallback;}}
function storageInventory(){const out=[];let chars=0;for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i)||'';const val=localStorage.getItem(key)||'';chars+=key.length+val.length;if(/^cec_/i.test(key))out.push({key,chars:val.length});}out.sort((a,b)=>a.key.localeCompare(b.key));return{keys:out,totalKeys:localStorage.length,totalChars:chars};}
function activeScreen(){const candidates=['.screen.active','.app-screen.active','[data-screen].active','section.active','.page.active'];for(const q of candidates){const el=$(q);if(el)return el.id||el.getAttribute('data-screen')||clip(el.className,120);}const visible=$$('main section,main .screen,.screen').find(el=>{const st=getComputedStyle(el);return st.display!=='none'&&st.visibility!=='hidden'&&el.offsetHeight>0;});return visible?.id||'no_identificada';}
function nativeInfo(){try{if(window.AndroidBridge&&typeof AndroidBridge.getDiagnostics==='function'){const raw=AndroidBridge.getDiagnostics();return raw?JSON.parse(raw):{};}}catch(e){addEvent('native_diag_error',e.message||String(e));}return{};}
function moduleInfo(){const defs=[['Carritos','CongElCalafateCarritos'],['Carritos compactos','CongElCalafateCarritosCompact'],['Horarios compactos','CongElCalafateCarritosCompactShifts'],['Territorios base','CongElCalafateTerritoriosV150'],['Territorios mapa individual','CongElCalafateTerritoriosV162'],['Informe territorios','CongElCalafateTerritoriosReportV162'],['Datos oficiales','CongTerritoryOfficialData']];return defs.map(([label,k])=>{const v=window[k];return{label,key:k,ok:!!v,version:v?.version||v?.VERSION||''};});}
function territoryInfo(){const off=window.CongTerritoryOfficialData||{};const data=off.data||{};const selected=String($('#t15Select')?.value||$('.cec-v162-select')?.value||'');const n=selected||'—';const item=data[selected]||null;const state=readJson('cec_territory_official_v150',{});const st=state[selected]||{};const done=st.done||{};let total=0;if(item){total=item.type==='tramos'?(item.items||[]).length:(item.items||[]).length*4;}const doneCount=Object.values(done).filter(Boolean).length;const pct=total?Math.round(doneCount*100/total):0;const drawings=readJson('cec_territory_individual_drawings_v162',{});const strokeCount=Array.isArray(drawings[selected])?drawings[selected].length:0;const img=$('.cec-v162-stage img,#cecV162MapImg,.cec-v162-map-img');const mapStatus=img?`${img.complete&&img.naturalWidth>0?'cargado':'pendiente'}${img.naturalWidth?` · ${img.naturalWidth}×${img.naturalHeight}`:''}`:'visor no visible';return{selected:n,officialCount:Object.keys(data).length,type:item?.type||'—',items:item?.items?.length||0,done:doneCount,total,pct,strokeCount,mapStatus};}
function carritosInfo(){const active=$('#cecV141Overview .cec-v141-bar.active,.cec-v141-bar.active,.cec-chip.active');const day=$('.cec-c-day.active,.cec-day-chip.active,.cec-c-days .active');const overrides=readJson('cec_carritos_v140_overrides',{});const recents=readJson('cec_carritos_v140_recent',[]);const inv=storageInventory();const caches=inv.keys.filter(x=>x.key.startsWith('cec_carritos_v140_csv_'));let overrideCount=0;try{overrideCount=Object.keys(overrides||{}).length;}catch(_){ }return{active:clip(active?.textContent||'no visible',180),day:clip(day?.textContent||'no visible',120),overrideCount,recentCount:Array.isArray(recents)?recents.length:Object.keys(recents||{}).length,cacheCount:caches.length,cacheChars:caches.reduce((s,x)=>s+x.chars,0)};}
function uiSnapshot(){const id=activeScreen();let el=id&&id!=='no_identificada'?document.getElementById(id):null;if(!el)el=$('.screen.active,.app-screen.active,[data-screen].active,main')||document.body;return clip(el?.innerText||'',1800);}
function networkInfo(){const c=navigator.connection||navigator.mozConnection||navigator.webkitConnection;return{online:navigator.onLine,effectiveType:c?.effectiveType||'',downlink:c?.downlink??'',rtt:c?.rtt??'',saveData:c?.saveData??''};}
function checks(native,terr,mods){const arr=[];const add=(name,ok,detail)=>arr.push({name,ok:!!ok,detail});add('DOM listo',document.readyState==='complete'||document.readyState==='interactive',document.readyState);add('Puente Android',!!window.AndroidBridge,window.AndroidBridge?'disponible':'ausente');add('Datos territorios',terr.officialCount===102,`${terr.officialCount}/102`);add('Módulo mapa individual',!!window.CongElCalafateTerritoriosV162,window.CongElCalafateTerritoriosV162?.version||'ausente');add('Módulo carritos',!!window.CongElCalafateCarritos,window.CongElCalafateCarritos?.version||'presente sin versión');add('Exportación nativa',typeof window.AndroidBridge?.saveDiagnosticText==='function',typeof window.AndroidBridge?.saveDiagnosticText==='function'?'disponible':'fallback web');add('Versión nativa',!!native.appVersion,native.appVersion||'no informada');const missing=mods.filter(m=>!m.ok&&m.key!=='CongElCalafateTerritoriosReportV162').map(m=>m.label);add('Módulos esenciales',missing.length===0,missing.length?`faltan: ${missing.join(', ')}`:'OK');return arr;}
function report(){const native=nativeInfo();const terr=territoryInfo();const carts=carritosInfo();const mods=moduleInfo();const store=storageInventory();const net=networkInfo();const ck=checks(native,terr,mods);const ok=ck.filter(x=>x.ok).length;const lines=[];const p=(k,v)=>lines.push(`${k}: ${v===undefined||v===null?'':v}`);lines.push('=== DIAGNÓSTICO · CONG EL CALAFATE ===');p('Generado',new Date().toLocaleString());p('ISO',nowIso());p('Versión módulo diagnóstico',VERSION);p('Sesión abierta hace',`${Math.round((Date.now()-STARTED_AT)/1000)} s`);p('Resumen',`${ok}/${ck.length} comprobaciones OK`);lines.push('');lines.push('--- APP / DISPOSITIVO ---');p('App',native.appName||'Cong El Calafate');p('Versión app',native.appVersion||VERSION);p('VersionCode',native.versionCode||'—');p('Package',native.packageName||'app.congregacion.elcalafate');p('Android SDK',native.androidSdk||'—');p('Fabricante',native.manufacturer||'—');p('Modelo',native.model||'—');p('Idioma nativo',native.locale||'—');p('User-Agent',navigator.userAgent);p('Idioma WebView',navigator.language||'—');p('Viewport',`${innerWidth}×${innerHeight} · DPR ${devicePixelRatio||1}`);lines.push('');lines.push('--- CONECTIVIDAD ---');p('Online',net.online);p('Tipo efectivo',net.effectiveType||'—');p('Downlink',net.downlink===''?'—':net.downlink);p('RTT',net.rtt===''?'—':net.rtt);p('Ahorro de datos',net.saveData===''?'—':net.saveData);lines.push('');lines.push('--- PANTALLA / UI ---');p('Pantalla activa',activeScreen());p('URL local',location.href);p('Texto visible (recorte)',uiSnapshot()||'—');lines.push('');lines.push('--- TERRITORIOS ---');p('Territorio seleccionado',terr.selected);p('Territorios oficiales cargados',terr.officialCount);p('Tipo',terr.type);p('Elementos base',terr.items);p('Progreso',`${terr.done}/${terr.total} · ${terr.pct}%`);p('Trazos guardados',terr.strokeCount);p('Plano individual',terr.mapStatus);lines.push('');lines.push('--- CARRITOS ---');p('Carrito activo',carts.active);p('Día seleccionado',carts.day);p('Cambios locales',carts.overrideCount);p('Nombres recientes',carts.recentCount);p('Cachés CSV',`${carts.cacheCount} · ${carts.cacheChars} chars`);lines.push('');lines.push('--- MÓDULOS ---');mods.forEach(m=>p(m.label,`${m.ok?'OK':'AUSENTE'}${m.version?' · v'+m.version:''}`));lines.push('');lines.push('--- COMPROBACIONES ---');ck.forEach(c=>lines.push(`${c.ok?'OK':'FALLO'} · ${c.name} · ${c.detail}`));lines.push('');lines.push('--- ALMACENAMIENTO LOCAL ---');p('Claves totales',store.totalKeys);p('Tamaño aproximado',`${store.totalChars} chars`);store.keys.forEach(x=>lines.push(`- ${x.key}: ${x.chars} chars`));lines.push('');lines.push('--- EVENTOS / ERRORES RECIENTES ---');if(!events.length)lines.push('Sin errores o eventos de backend capturados desde que se cargó el diagnóstico.');else events.forEach(e=>lines.push(`${e.at} · ${e.type} · ${e.detail}`));lines.push('');lines.push('--- FIN DIAGNÓSTICO ---');lines.push('Nota: este informe evita contraseñas, identificadores únicos y ubicación precisa. Puede contener nombres/textos actualmente visibles en la pantalla para facilitar el diagnóstico.');return lines.join('\n');}
function installStyle(){if($('#cecDiagStyle'))return;const s=document.createElement('style');s.id='cecDiagStyle';s.textContent=`.cec-diag-fab{position:fixed;right:14px;bottom:calc(88px + env(safe-area-inset-bottom));z-index:9995;border:0;border-radius:999px;background:#163f53;color:#fff;font-weight:900;font-size:12px;padding:12px 15px;box-shadow:0 8px 24px rgba(15,52,68,.28);letter-spacing:.01em}.cec-diag-fab:active{transform:scale(.97)}.cec-diag-overlay{position:fixed;inset:0;z-index:10020;background:rgba(8,28,38,.55);display:none;align-items:flex-end;justify-content:center;padding:0}.cec-diag-overlay.open{display:flex}.cec-diag-panel{width:min(100%,760px);height:min(92vh,880px);background:#f7fafb;border-radius:24px 24px 0 0;box-shadow:0 -12px 40px rgba(0,0,0,.22);display:flex;flex-direction:column;overflow:hidden}.cec-diag-head{display:flex;align-items:center;gap:10px;padding:16px 16px 12px;background:#fff;border-bottom:1px solid #dbe7eb}.cec-diag-head>div{flex:1;min-width:0}.cec-diag-head strong{display:block;color:#163f53;font-size:18px}.cec-diag-head small{display:block;color:#6d828c;font-size:11px;margin-top:2px}.cec-diag-close{border:1px solid #d7e2e6;background:#f5f8f9;color:#274e5e;border-radius:12px;height:40px;padding:0 13px;font-weight:900}.cec-diag-summary{display:flex;gap:8px;flex-wrap:wrap;padding:10px 14px;background:#eef5f7;border-bottom:1px solid #dce7ea;font-size:11px;color:#466573}.cec-diag-chip{background:#fff;border:1px solid #d7e4e8;border-radius:999px;padding:6px 9px;font-weight:800}.cec-diag-text{flex:1;width:100%;box-sizing:border-box;border:0;resize:none;outline:0;padding:14px;background:#102832;color:#eaf4f7;font:11px/1.5 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;white-space:pre;overflow:auto}.cec-diag-actions{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;padding:12px 14px calc(12px + env(safe-area-inset-bottom));background:#fff;border-top:1px solid #dce7ea}.cec-diag-btn{min-height:44px;border-radius:12px;border:1px solid #cfdee4;background:#f5f9fa;color:#244f60;font-weight:900;font-size:12px}.cec-diag-btn.primary{background:#0b6e55;border-color:#0b6e55;color:#fff}.cec-diag-btn.download{background:#0b5fa5;border-color:#0b5fa5;color:#fff}.cec-diag-toast{position:fixed;left:50%;bottom:calc(155px + env(safe-area-inset-bottom));transform:translateX(-50%);z-index:10050;background:#102f3d;color:#fff;border-radius:999px;padding:9px 13px;font-size:11px;font-weight:800;opacity:0;pointer-events:none;transition:opacity .18s}.cec-diag-toast.show{opacity:1}@media(max-width:430px){.cec-diag-actions{grid-template-columns:1fr 1fr}.cec-diag-actions .refresh{grid-column:1/-1;order:3}.cec-diag-panel{height:94vh}}`;document.head.appendChild(s);}
function toast(msg){let t=$('#cecDiagToast');if(!t){t=document.createElement('div');t.id='cecDiagToast';t.className='cec-diag-toast';document.body.appendChild(t);}t.textContent=msg;t.classList.add('show');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.remove('show'),1800);}
function filename(){return `diagnostico_cong_el_calafate_${new Date().toISOString().replace(/[:.]/g,'-')}.txt`;}
function refresh(){const ta=$('#cecDiagText');if(!ta)return;ta.value=report();const terr=territoryInfo();const sum=$('#cecDiagSummary');if(sum)sum.innerHTML=`<span class="cec-diag-chip">App ${esc(nativeInfo().appVersion||VERSION)}</span><span class="cec-diag-chip">Pantalla: ${esc(activeScreen())}</span><span class="cec-diag-chip">Territorio ${esc(terr.selected)} · ${terr.pct}%</span><span class="cec-diag-chip">Eventos: ${events.length}</span>`;}
async function copyReport(){const text=$('#cecDiagText')?.value||report();try{if(window.AndroidBridge&&typeof AndroidBridge.copyText==='function'){AndroidBridge.copyText(text);toast('Diagnóstico copiado');return;}}catch(_){ }try{await navigator.clipboard.writeText(text);toast('Diagnóstico copiado');return;}catch(_){ }const ta=$('#cecDiagText');if(ta){ta.focus();ta.select();try{document.execCommand('copy');toast('Diagnóstico copiado');return;}catch(_){ }}toast('No se pudo copiar automáticamente');}
function downloadReport(){const text=$('#cecDiagText')?.value||report(),name=filename();try{if(window.AndroidBridge&&typeof AndroidBridge.saveDiagnosticText==='function'){AndroidBridge.saveDiagnosticText(name,text);toast('Guardando TXT en Descargas…');return;}}catch(e){addEvent('download_native_error',e.message||String(e));}try{const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Descarga iniciada');}catch(e){addEvent('download_web_error',e.message||String(e));toast('No se pudo descargar; use Copiar');}}
function open(){const o=$('#cecDiagOverlay');if(!o)return;refresh();o.classList.add('open');document.body.style.overflow='hidden';}
function close(){const o=$('#cecDiagOverlay');if(o)o.classList.remove('open');document.body.style.overflow='';}
function installUI(){if($('#cecDiagFab'))return;installStyle();const fab=document.createElement('button');fab.id='cecDiagFab';fab.className='cec-diag-fab';fab.type='button';fab.textContent='Diagnóstico';fab.setAttribute('aria-label','Abrir diagnóstico del app');fab.addEventListener('click',open);document.body.appendChild(fab);const ov=document.createElement('div');ov.id='cecDiagOverlay';ov.className='cec-diag-overlay';ov.innerHTML=`<section class="cec-diag-panel" role="dialog" aria-modal="true" aria-label="Diagnóstico del app"><header class="cec-diag-head"><div><strong>Diagnóstico del app</strong><small>Copie o descargue el TXT y reenvíelo para revisar errores.</small></div><button type="button" class="cec-diag-close" id="cecDiagClose">Cerrar</button></header><div class="cec-diag-summary" id="cecDiagSummary"></div><textarea id="cecDiagText" class="cec-diag-text" readonly spellcheck="false"></textarea><footer class="cec-diag-actions"><button type="button" class="cec-diag-btn primary" id="cecDiagCopy">Copiar</button><button type="button" class="cec-diag-btn download" id="cecDiagDownload">Descargar TXT</button><button type="button" class="cec-diag-btn refresh" id="cecDiagRefresh">Actualizar diagnóstico</button></footer></section>`;ov.addEventListener('click',e=>{if(e.target===ov)close();});document.body.appendChild(ov);$('#cecDiagClose').addEventListener('click',close);$('#cecDiagCopy').addEventListener('click',copyReport);$('#cecDiagDownload').addEventListener('click',downloadReport);$('#cecDiagRefresh').addEventListener('click',()=>{refresh();toast('Diagnóstico actualizado');});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',installUI,{once:true});else installUI();
window.CongElCalafateDiagnostico={version:VERSION,report,open,refresh,log:addEvent};
addEvent('diagnostic_ready',`V${VERSION}`);
})();
